<?php require '../../config/db.php';require '../../includes/functions.php';require '../../includes/auth.php';require_admin();if(!csrf_ok($_POST['csrf']??''))json_response(false,'Security token expired.',[],419);$id=(int)($_POST['id']??0);$action=$_POST['action']??'';if(!$id||!in_array($action,['sold','archive','restore']))json_response(false,'Invalid product action.',[],422);$q=$pdo->prepare('SELECT quantity FROM products WHERE id=?');$q->execute([$id]);$before=$q->fetchColumn();if($before===false)json_response(false,'Product not found.',[],404);if($action==='sold'){$pdo->beginTransaction();try{if((int)$before>0){$pdo->prepare('INSERT INTO stock_transactions(product_id,type,quantity,stock_before,stock_after,reason,reference_no,user_id) VALUES(?,?,?,?,?,?,?,?)')->execute([$id,'OUT',(int)$before,(int)$before,0,'Marked as sold','SOLD-'.date('YmdHis'),admin_user()['id']]);}$pdo->prepare("UPDATE products SET quantity=0,status='sold' WHERE id=?")->execute([$id]);$pdo->commit();json_response(true,'Product marked as sold.');}catch(Throwable $e){$pdo->rollBack();json_response(false,$e->getMessage(),[],422);}}$status=$action==='archive'?'archived':'active';$pdo->prepare('UPDATE products SET status=? WHERE id=?')->execute([$status,$id]);json_response(true,$action==='archive'?'Product archived.':'Product restored.');